# First, let me extract all unique connected components from input by any color
def get_all_components(grid):
    """Get all connected components regardless of color"""
    result = []
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r,c) not in visited:
                # BFS for component
                component = []
                queue = [(r, c)]
                visited.add((r, c))

                idx = 0
                while idx < len(queue):
                    cr, cc = queue[idx]
                    idx += 1
                    component.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] != 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                result.append(sorted(component))

    return result

